38: function renderSquad(){const max=5;$('#squadLimit').textContent=`${state.squad.length} / ${max}`;$('#rosterList').innerHTML=state.squad.map(u=>`<div class="roster-row"><span class="person-avatar">${u.letter}</span><div class="roster-info"><h3>${u.name}</h3><p>${u.role} · ${u.hp} VITALITY</p></div><span class="roster-level">LVL ${Math.max(1,1+Math.floor(state.xp/250))}</span>${u.id==='player'?'':`<button class="release-btn" data-release="${u.id}">DISMISS</button>`}</div>`).join('');$$('[data-release]').forEach(b=>b.onclick=()=>{if(state.squad.length<=2)return toast('A patrol must have at least two members.');state.squad=state.squad.filter(u=>u.id!==b.dataset.release);save();renderSquad()});const available=recruitCatalog.filter(r=>!state.squad.some(u=>u.id===r.id));$('#recruitList').innerHTML=available.map(r=>`<div class="recruit-row"><span class="person-avatar">${r.letter}</span><div class="recruit-copy"><h3>${r.name}</h3><small>${r.role}</small><p>${r.perk}</p><div class="recruit-bottom"><b>$${r.price}</b><button class="gear-action" data-recruit="${r.id}" ${state.squad.length>=max?'disabled':''}>${state.squad.length>=max?'PATROL FULL':'RECRUIT'}</button></div></div></div>`).join('')||'<p>Every available specialist is already on your roster.</p>';$$('[data-recruit]').forEach(b=>b.onclick=()=>{const r=recruitCatalog.find(x=>x.id===b.dataset.recruit);if(state.squad.length>=max)return toast('Patrol roster is full.');if(state.scratch<r.price)return toast('Not enough scratch.');state.scratch-=r.price;state.squad.push({id:r.id,name:r.name,role:r.role,letter:r.letter,hp:r.hp,damage:r.damage,accuracy:r.accuracy,medic:!!r.medic});save();renderSquad();toast(`${r.name} joined the patrol.`)})}
