 let battle=null;
 const enemyNames=['VC SCOUT','NVA RIFLEMAN','VC GUERRILLA','NVA PATROLMAN','VC VETERAN','NVA SCOUT'];
 function deploy(){if(state.mission>=missionCatalog.length){showCampaignComplete();return}const m=mission();const starts=[[1,4],[1,2],[0,4],[0,1],[1,5]];const positions=[[5,1],[6,3],[5,4],[7,2],[6,5],[7,0]];battle={turn:1,phase:'player',mode:null,selected:null,units:state.squad.map((u,i)=>({...u,hp:u.hp,maxHp:u.hp,damage:u.id==='player'?weaponById(state.equippedWeapon).damage:u.damage,accuracy:u.id==='player'?weaponById(state.equippedWeapon).accuracy:u.accuracy,x:starts[i][0],y:starts[i][1],spent:false,alive:true})),enemies:Array.from({length:m.enemies},(_,i)=>({id:'e'+i,name:enemyNames[i%enemyNames.length],hp:20+Math.floor(state.mission*2),maxHp:20+Math.floor(state.mission*2),x:positions[i][0],y:positions[i][1],alive:true})),logs:[],kills:0,medicUsed:false};$('#battleMissionTitle').textContent=m.name;$('#battleFaction').textContent=factions.find(f=>f.id===state.faction).name;$('#mapSector').textContent=m.sector;$('#objectiveLabel').textContent=`OBJECTIVE: ${m.objective}`;$('.map-weather').textContent=`☁ ${m.weather} · VISIBILITY 4`;setScreen('battleScreen');log(`Patrol deployed in ${m.region.toLowerCase()}.`,'green');log(`${m.enemies} hostile contacts reported in the area.`);renderBattle()}
 const idx=(x,y)=>y*8+x,dist=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
-function renderBattle(){if(!battle)return;const map=$('#battleMap');map.innerHTML='';const aliveEnemies=battle.enemies.filter(e=>e.alive);for(let y=0;y<6;y++)for(let x=0;x<8;x++){const terrain=(x*13+y*7+state.mission*3)%11;const tile=document.createElement('button');tile.type='button';tile.className='tile'+(terrain===0||terrain===4?' cover':'')+(terrain===5?' water':'')+(terrain===8?' path':'');tile.dataset.x=x;tile.dataset.y=y;tile.setAttribute('role','gridcell');tile.setAttribute('aria-label',`Map tile ${String.fromCharCode(65+y)}-${x+1}`);const unit=battle.units.find(u=>u.alive&&u.x===x&&u.y===y),enemy=battle.enemies.find(e=>e.alive&&e.x===x&&e.y===y);let html=`<span class="tile-coord">${String.fromCharCode(65+y)}${x+1}</span>`;if(unit)html+=`<span class="tile-content"><span class="tile-unit ${battle.selected===unit.id?'selected':''}" aria-label="${unit.name}">${unit.letter}<span class="health-pip"><i style="width:${unit.hp/unit.maxHp*100}%"></i></span></span><span class="tile-label">${unit.name.split(' ').slice(-1)[0]}</span></span>`;if(enemy)html+=`<span class="tile-content"><span class="tile-unit enemy" aria-label="${enemy.name}">!</span><span class="tile-label">${enemy.name}</span><span class="health-pip"><i style="width:${enemy.hp/enemy.maxHp*100}%"></i></span></span>`;if(unit&&battle.selected===unit.id)tile.classList.add('selected');if(battle.mode==='move'&&battle.selected){const u=getSelected();if(!unit&&!enemy&&Math.abs(u.x-x)+Math.abs(u.y-y)<=moveDistance())tile.classList.add('move-target')}if(battle.mode==='fire'&&enemy&&battle.selected&&dist(getSelected(),enemy)<=weaponById(state.equippedWeapon).range)tile.classList.add('attack-target');tile.innerHTML=html;tile.onclick=()=>onTile(x,y);map.append(tile)}
+function renderBattle(){if(!battle)return;const map=$('#battleMap');map.innerHTML='';const aliveEnemies=battle.enemies.filter(e=>e.alive);for(let y=0;y<6;y++)for(let x=0;x<8;x++){const terrain=(x*13+y*7+state.mission*3)%11;const tile=document.createElement('button');tile.type='button';tile.className='tile'+(terrain===0||terrain===4?' cover':'')+(terrain===5?' water':'')+(terrain===8?' path':'');tile.dataset.x=x;tile.dataset.y=y;tile.setAttribute('role','gridcell');tile.setAttribute('aria-label',`Map tile ${String.fromCharCode(65+y)}-${x+1}`);const unit=battle.units.find(u=>u.alive&&u.x===x&&u.y===y),enemy=battle.enemies.find(e=>e.alive&&e.x===x&&e.y===y);let html=`<span class="tile-coord">${String.fromCharCode(65+y)}${x+1}</span>`;if(unit)html+=`<span class="tile-content"><span class="tile-unit ${battle.selected===unit.id?'selected':''}" aria-label="${unit.name}">${unit.letter}<span class="health-pip"><i style="width:${unit.hp/unit.maxHp*100}%"></i></span></span><span class="tile-label">${unit.name.split(' ').slice(-1)[0]}</span></span>`;if(enemy)html+=`<span class="tile-content"><span class="tile-unit enemy" aria-label="${enemy.name}">!</span><span class="tile-label">${enemy.name}</span><span class="health-pip"><i style="width:${enemy.hp/enemy.maxHp*100}%"></i></span></span>`;if(unit&&battle.selected===unit.id)tile.classList.add('selected');if(battle.mode==='move'&&battle.selected){const u=getSelected();if(!unit&&!enemy&&Math.abs(u.x-x)+Math.abs(u.y-y)<=moveDistance())tile.classList.add('move-target')}if(battle.mode==='fire'&&enemy&&battle.selected&&dist(getSelected(),enemy)<=weaponFor(getSelected()).range)tile.classList.add('attack-target');tile.innerHTML=html;tile.onclick=()=>onTile(x,y);map.append(tile)}
 $('#remainingLabel').textContent=`CONTACTS ${String(aliveEnemies.length).padStart(2,'0')}`;$('#aliveCount').textContent=String(battle.units.filter(u=>u.alive).length).padStart(2,'0');$('#turnLabel').textContent=battle.phase==='player'?`YOUR TURN · ${String(battle.turn).padStart(2,'0')}`:'HOSTILE TURN';$('#endTurnBtn').disabled=battle.phase!=='player';$('#unitList').innerHTML=battle.units.filter(u=>u.alive).map(u=>`<div class="unit-row ${battle.selected===u.id?'active':''}" data-unit="${u.id}"><span class="unit-mini">${u.letter}</span><div class="unit-row-info"><b>${u.name}</b><small>${u.role}</small></div><span class="${u.spent?'unit-row-spent':'unit-row-hp'}">${u.spent?'DONE':`${u.hp}/${u.maxHp} HP`}</span></div>`).join('')||'<small>No patrol members remain.</small>';$$('[data-unit]').forEach(el=>el.onclick=()=>selectUnit(el.dataset.unit));renderSelected();$('#moveBtn').disabled=!canCommand();$('#fireBtn').disabled=!canCommand();$('#holdBtn').disabled=!canCommand();$('#actionHint').textContent=battle.phase!=='player'?'HOSTILE TURN':battle.mode==='move'?'SELECT DESTINATION':battle.mode==='fire'?'SELECT HOSTILE':'SELECT A SOLDIER';$('#logEntries').innerHTML=battle.logs.slice(-5).reverse().map(l=>`<div class="log-entry">${l}</div>`).join('');}
 function getSelected(){return battle.units.find(u=>u.id===battle.selected)}function canCommand(){const u=getSelected();return battle&&battle.phase==='player'&&u&&u.alive&&!u.spent}function moveDistance(){return 2+(state.faction==='sog'?1:0)}
 function renderSelected(){const box=$('#selectedCard'),u=getSelected();if(!u){box.innerHTML='<div class="eyebrow">NO SOLDIER SELECTED</div><p>Choose an available patrol member to issue a command.</p>';return}box.innerHTML=`<div><h3>${u.name}</h3><span class="selected-role">${u.role}</span></div><p>${u.hp} / ${u.maxHp} VITALITY ${u.spent?'· ACTION SPENT':'· READY'}</p><div class="health-track"><i style="width:${u.hp/u.maxHp*100}%"></i></div><div class="unit-stats"><span>HIT CHANCE <b>${Math.min(95,u.accuracy+(state.faction==='marines'?5:0))}%</b></span><span>WEAPON <b>${u.id==='player'?weaponById(state.equippedWeapon).name.split(' ').slice(-1)[0]:'SERVICE RIFLE'}</b></span></div>`}
 function selectUnit(id){if(battle.phase!=='player')return;const u=battle.units.find(v=>v.id===id);if(!u||u.spent)return;battle.selected=id;battle.mode=null;renderBattle()}

